import importlib
for m in ["scipy","numpy","pulp","pyomo","cvxpy","highspy","mip","ortools"]:
    try:
        mod = importlib.import_module(m)
        print(m, "OK", getattr(mod, "__version__", "?"))
    except Exception as e:
        print(m, "MISSING", type(e).__name__)
